    let currentLanguage = "zh-Hant";
    let formSubmissionState = "idle";
    const translatableTextNodes = [];
    const translatableAttributes = [];

    function translatedText(original, lang = currentLanguage){
      if(lang === "zh-Hant") return original;
      return STATIC_TRANSLATIONS[lang]?.[original] ?? original;
    }

    function registerTranslatableContent(){
      const walker = document.createTreeWalker(
        document.documentElement,
        NodeFilter.SHOW_TEXT,
        {
          acceptNode(node){
            const parent = node.parentElement;
            if(!parent || parent.closest("script, style, .language-switcher, #submitInquiryButton, #prototypeMessage")){
              return NodeFilter.FILTER_REJECT;
            }
            return node.nodeValue.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
          }
        }
      );

      while(walker.nextNode()){
        const node = walker.currentNode;
        const match = node.nodeValue.match(/^(\s*)([\s\S]*?)(\s*)$/);
        if(!match || !match[2]) continue;
        translatableTextNodes.push({
          node,
          before: match[1],
          original: match[2],
          after: match[3]
        });
      }

      document.querySelectorAll("[placeholder], [aria-label], [title], [alt], input[type='hidden'][value]").forEach(element => {
        ["placeholder","aria-label","title","alt","value"].forEach(attribute => {
          if(!element.hasAttribute(attribute)) return;
          if(attribute === "value" && element.matches("input:not([type='hidden'])")) return;
          translatableAttributes.push({
            element,
            attribute,
            original: element.getAttribute(attribute)
          });
        });
      });
    }

    function renderFormSubmissionState(){
      const emailButton = document.getElementById("submitInquiryButton");
      const whatsappButton = document.getElementById("whatsappInquiryButton");
      const message = document.getElementById("prototypeMessage");
      if(emailButton) emailButton.textContent = translatedText("電郵提交");
      if(whatsappButton) whatsappButton.textContent = translatedText("WhatsApp 查詢");
      if(!message) return;

      if(formSubmissionState === "email"){
        message.style.display = "block";
        message.textContent = translatedText("已開啟電郵應用，請確認內容後按「傳送」。");
      }else if(formSubmissionState === "whatsapp"){
        message.style.display = "block";
        message.textContent = translatedText("已開啟 WhatsApp，請確認內容後按「傳送」。");
      }else{
        message.style.display = "none";
        message.textContent = translatedText("已開啟電郵應用，請確認內容後按「傳送」。");
      }
    }

    function applyLanguage(lang, remember = true){
      currentLanguage = ["zh-Hant","zh-Hans","en"].includes(lang) ? lang : "zh-Hant";

      document.documentElement.lang =
        currentLanguage === "zh-Hant" ? "zh-Hant-HK" :
        currentLanguage === "zh-Hans" ? "zh-Hans" : "en";

      translatableTextNodes.forEach(record => {
        record.node.nodeValue =
          record.before + translatedText(record.original) + record.after;
      });

      translatableAttributes.forEach(record => {
        record.element.setAttribute(
          record.attribute,
          translatedText(record.original)
        );
      });

      const selector = document.getElementById("languageSelect");
      if(selector) selector.value = currentLanguage;

      renderFormSubmissionState();

      if(remember){
        try{ localStorage.setItem("bottizLanguage", currentLanguage); }catch(error){}
      }
    }

    function initialiseLanguageSwitcher(){
      registerTranslatableContent();

      let savedLanguage = "zh-Hant";
      try{ savedLanguage = localStorage.getItem("bottizLanguage") || "zh-Hant"; }catch(error){}

      const selector = document.getElementById("languageSelect");
      selector?.addEventListener("change", event => applyLanguage(event.target.value));
      applyLanguage(savedLanguage, false);
    }

    document.querySelectorAll(".filter").forEach(btn => {
      btn.addEventListener("click", () => {
        document.querySelectorAll(".filter").forEach(x => x.classList.remove("active"));
        btn.classList.add("active");
        const filter = btn.dataset.filter;
        document.querySelectorAll(".card").forEach(card => {
          const categories = card.dataset.category.split(/\s+/);
          card.style.display = filter === "all" || categories.includes(filter) ? "" : "none";
        });
      });
    });


    function showProductCategory(filter){
      const button = document.querySelector(`.filter[data-filter="${filter}"]`);
      if(button) button.click();
      document.getElementById("products")?.scrollIntoView({behavior:"smooth", block:"start"});
    }

    function scrollToId(id){
      document.getElementById(id)?.scrollIntoView({behavior:"smooth"});
    }

    function openContact(product=""){
      const interestField = document.getElementById("interestInput");
      if(interestField) interestField.value = product;
      formSubmissionState = "idle";
      renderFormSubmissionState();
      openModal("contactModal");
    }

    function collectEnquiryData(){
      return {
        name: document.getElementById("nameInput")?.value.trim() || "",
        company: document.getElementById("companyInput")?.value.trim() || "",
        email: document.getElementById("emailInput")?.value.trim() || "",
        phone: document.getElementById("phoneInput")?.value.trim() || "",
        inquiryType: document.getElementById("inquiryTypeSelect")?.value.trim() || "",
        product: document.getElementById("interestInput")?.value.trim() || "",
        message: document.getElementById("messageInput")?.value.trim() || ""
      };
    }

    function enquiryCopy(data){
      if(currentLanguage === "en"){
        return {
          subject: `New Bottiz Enquiry — ${data.name || "Website Visitor"}`,
          body: [
            "Hello Bottiz team,",
            "",
            "I would like to enquire about your robot solutions.",
            "",
            `Name: ${data.name}`,
            `Company / Organisation: ${data.company || "Not provided"}`,
            `Email: ${data.email}`,
            `Phone: ${data.phone || "Not provided"}`,
            `Enquiry Type: ${data.inquiryType || "Not specified"}`,
            `Product / Solution of Interest: ${data.product || "Not specified"}`,
            `Details: ${data.message}`,
            "",
            "Please contact me to discuss further. Thank you."
          ].join("\n")
        };
      }

      if(currentLanguage === "zh-Hans"){
        return {
          subject: `Bottiz 新咨询｜${data.name || "网站访客"}`,
          body: [
            "Bottiz 团队您好：",
            "",
            "我想咨询贵公司的机器人方案，资料如下：",
            "",
            `姓名：${data.name}`,
            `公司／机构名称：${data.company || "未提供"}`,
            `电子邮箱：${data.email}`,
            `电话号码：${data.phone || "未提供"}`,
            `查询类型：${data.inquiryType || "未指定"}`,
            `感兴趣的产品／方案：${data.product || "未指定"}`,
            `详细说明：${data.message}`,
            "",
            "请与我联系进一步了解方案，谢谢。"
          ].join("\n")
        };
      }

      return {
        subject: `Bottiz 新查詢｜${data.name || "網站訪客"}`,
        body: [
          "Bottiz 團隊您好：",
          "",
          "我想查詢貴公司的機器人方案，資料如下：",
          "",
          `姓名：${data.name}`,
          `公司／機構名稱：${data.company || "未提供"}`,
          `電子郵箱：${data.email}`,
          `電話號碼：${data.phone || "未提供"}`,
          `查詢類型：${data.inquiryType || "未指定"}`,
          `感興趣的產品／方案：${data.product || "未指定"}`,
          `詳細說明：${data.message}`,
          "",
          "請與我聯絡進一步了解方案，謝謝。"
        ].join("\n")
      };
    }

    function validateEnquiryForm(){
      const form = document.getElementById("inquiryForm");
      if(!form) return false;
      if(!form.reportValidity()) return false;
      return true;
    }

    function handleEmailSubmit(event){
      event.preventDefault();
      if(!validateEnquiryForm()) return;

      const copy = enquiryCopy(collectEnquiryData());
      formSubmissionState = "email";
      renderFormSubmissionState();

      window.location.href = `mailto:support@bottiz.com?subject=${encodeURIComponent(copy.subject)}&body=${encodeURIComponent(copy.body)}`;
    }

    function handleWhatsAppSubmit(){
      if(!validateEnquiryForm()) return;

      const copy = enquiryCopy(collectEnquiryData());
      formSubmissionState = "whatsapp";
      renderFormSubmissionState();

      const message = `${copy.subject}\n\n${copy.body}`;
      window.open(`https://wa.me/85295335639?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer");
    }

    function openModal(id){
      document.getElementById(id).classList.add("open");
      document.body.style.overflow = "hidden";
    }

    function closeModal(id){
      document.getElementById(id).classList.remove("open");
      document.body.style.overflow = "";
    }

    function backdropClose(event,id){
      if(event.target.id === id) closeModal(id);
    }

    function toggleMobileNav(){
      document.querySelector(".nav-links")?.classList.toggle("open");
    }

    document.addEventListener("keydown", e => {
      if(e.key === "Escape"){
        document.querySelectorAll(".modal.open").forEach(x => x.classList.remove("open"));
        document.body.style.overflow = "";
      }
    });


